class Solution {
public:
    int trap(vector<int>& height) {
        stack<int> st;
        int ans = 0;
        for (int i = 0; i < (int)height.size(); ++i) {
            while (!st.empty() && height[i] > height[st.top()]) {
                int mid = st.top(); st.pop();
                if (st.empty()) break;
                int h = min(height[i], height[st.top()]) - height[mid];
                int w = i - st.top() - 1;
                ans += h * w;
            }
            st.push(i);
        }
        return ans;
    }
};

